    const match = /^([\w.-]+)(?:#([\w-]+))?=(kill|pause)(?:@(\d+))?$/.exec(item);
    if (!match) throw new Error(`bad failpoint rule: ${item}`);
    parsed.push({
      key: item.split('=')[0],
      name: match[1],
      type: match[2] ?? null,
      action: match[3],
