try {
  // Only the holder of the queue lock compacts, so a temp file that is already
  // here was left by an attempt that died or failed. Clear it, or one such
  // attempt would block every later one. Exclusive create still guards against
  // anything else writing the same name.
  ops.unlink(tempPath);
  ops.create(tempPath, { exclusive: true });
  ops.writeAt(tempPath, bytes, 0);
  // The bytes must be durable before the name is: renaming an unsynced file over
  // the log and then losing power leaves an empty log.
  ops.sync(tempPath);
  hit('compact.after-tmp-write', { generation: nextGeneration });
  hit('compact.before-rename', { generation: nextGeneration });
  ops.rename(tempPath, wal.file);
  hit('compact.after-rename', { generation: nextGeneration });
  ops.syncDir(path.dirname(wal.file));
} catch (err) {
  // If the rename did not happen the temp file is garbage; if it did, it is gone.
  try {
    ops.unlink(tempPath);
  } catch {
    // The next compaction clears it again.
  }
  err.message = `compaction failed: ${err.message}`;
  throw err;
}

