catchUp() {
  const header = this.wal.readHeader();
  // A compaction by any process starts a new generation, and this process has to
  // read the new log from its start however long the old one and the new one are.
  // A log that is now shorter than what was read has been cut from outside.
  if (this.generation !== header.generation || this.wal.size() < this.offset) {
    this.state = createState();
    this.offset = HEADER_SIZE;
    this.snapshotBytes = 0;
    this.generation = header.generation;
  }

  // The offset moves with the state, so if the scan stops on damage, a later
  // catch-up does not apply the same records twice.
  const { end, tail } = this.wal.scanFrom(this.offset, (frames, upTo) => {
    for (const frame of frames) {
      applyRecord(this.state, frame.record);
      if (frame.record.t === 'snapshot') this.snapshotBytes = frame.size;
    }
    this.offset = upTo;
  });
  this.offset = end;

  if (tail) {
    // We hold the lock, and writes happen under it, so what is left after the
    // last whole record is a write that was cut off and never acknowledged. It
    // has to go before anything else is appended behind it.
    this.wal.truncate(end);
    this.tornTailsDropped += 1;
    log.warn('dropped incomplete tail', { offset: end, reason: tail.reason, bytes: tail.bytes });
  }
}

/** Must be called inside withLock(). */
append(records, options) {
  const before = this.offset;
  let end;
  try {
    end = this.wal.append(records, options);
  } catch (err) {
    // Not acknowledged, so it must not become a record later. Best effort: if
    // this fails too, the next catch-up finds the bytes as an incomplete tail.
    try {
      this.wal.truncate(before);
    } catch {
      // see above
    }
    throw err;
  }
  this.offset = end;
  // Apply what a reader of the log will see, not the caller's live objects.
  for (const record of records) applyRecord(this.state, JSON.parse(JSON.stringify(record)));
}

