   * extension is written to the log, because the process that reaps expired
   * leases is usually not the one that holds them.
   */
  heartbeat(id, token, { leaseMs = this.config.leaseMs } = {}) {
    return this.store.withLock(() => {
      const job = this.#require(id);
      this.#requireLease(job, token);
      const now = this.clock.now();
      const leaseUntil = now + leaseMs;
      // Not synced: a heartbeat lost with the machine only makes a lease look
      // older, and the next synced write carries it to disk anyway. It does have
      // to reach the file, where other processes read it.
      this.store.append([heartbeatRecord({ id, fence: token, leaseUntil, at: now })], { sync: false });
      this.store.maybeCompact();
      return { leaseUntil };
    });
