        if (job.status === 'done' && job.completionSeq !== null && job.completionSeq > after) commits.push(job);
      }
      commits.sort((a, b) => a.completionSeq - b.completionSeq);
      return commits.slice(0, limit).map((job) =>
        structuredClone({
          seq: job.completionSeq,
          id: job.id,
          token: job.fence,
          result: job.result,
          completedAt: job.completedAt,
        }),
