  /**
   * Gives up every lease held by a worker that is known to be dead, without
   * waiting for them to expire. The jobs are runnable at once, with no backoff;
   * the attempt still counts, so a job that is out of attempts goes dead. Jobs
   * the worker had already committed are left alone.
   */
  reclaimWorker(workerId, { reason = 'worker died' } = {}) {
    return this.store.withLock(() => {
      const now = this.clock.now();
      const records = [];
      const reclaimed = [];
      for (const job of this.store.state.jobs.values()) {
        if (job.status !== 'leased' || job.lease.worker !== workerId) continue;
        if (job.attempts >= job.maxAttempts) {
          records.push(deadRecord({ id: job.id, fence: job.fence, error: reason, at: now }));
          reclaimed.push({ id: job.id, status: 'dead' });
        } else {
          records.push(releaseRecord({ id: job.id, fence: job.fence, error: reason, at: now }));
          reclaimed.push({ id: job.id, status: 'ready' });
