// Runs one action against the queue in argv[2], for crash tests. Arm a failpoint
// (and WALQ_SIMULATE_POWER_LOSS=1) in the environment to have it die part way.
//
//   open          open the queue (creates it if needed)
//   enqueue N     enqueue N jobs, one call each
//   compact       compact once
//   run           claim one job as worker "doomed", then complete it
//   claim         claim one job as worker "doomed" and stop

import { openQueue } from '../../src/index.mjs';

const [dir, action, arg] = process.argv.slice(2);
const options = process.env.WALQ_TEST_OPTIONS ? JSON.parse(process.env.WALQ_TEST_OPTIONS) : {};
const queue = openQueue(dir, options);

if (action === 'enqueue') {
  for (let i = 0; i < Number(arg ?? 1); i += 1) queue.enqueue('x', { i });
} else if (action === 'compact') {
  queue.compact();
} else if (action === 'run' || action === 'claim') {
  const job = queue.claim('doomed');
  if (job && action === 'run') queue.complete(job.id, job.token, { done: job.id });
}
queue.close();

// Helpers for tests that kill a process at a failpoint and look at what is left.

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { tempDir } from './tmp.mjs';

const CHILD = fileURLToPath(new URL('./crash-child.mjs', import.meta.url));

/**
 * Runs `action` in a child process with `failpoints` armed and the power-loss model
 * on. Returns whether the failpoint fired (the marker file appeared).
 */
export function crashAt(t, dir, action, failpoints, { arg, options, powerLoss = true } = {}) {
  const markers = tempDir(t);
  const result = spawnSync(process.execPath, [CHILD, dir, action, String(arg ?? '')], {
    env: {
      ...process.env,
      WALQ_FAILPOINTS: failpoints,
      WALQ_FAILPOINT_DIR: markers,
      ...(powerLoss ? { WALQ_SIMULATE_POWER_LOSS: '1' } : {}),
      ...(options ? { WALQ_TEST_OPTIONS: JSON.stringify(options) } : {}),
    },
    encoding: 'utf8',
  });
  const name = failpoints.split(',')[0].split('=')[0].replace('#', '.');
  return { fired: fs.existsSync(path.join(markers, `${name}.hit`)), stderr: result.stderr, status: result.status };
}

/** Runs an action to the end with nothing armed. */
export function runChild(dir, action, { arg, options, powerLoss = true } = {}) {
  const result = spawnSync(process.execPath, [CHILD, dir, action, String(arg ?? '')], {
    env: {
      ...process.env,
      ...(powerLoss ? { WALQ_SIMULATE_POWER_LOSS: '1' } : {}),
      ...(options ? { WALQ_TEST_OPTIONS: JSON.stringify(options) } : {}),
    },
    encoding: 'utf8',
  });
  if (result.status !== 0) throw new Error(`child ${action} failed: ${result.stderr}`);
}

// G1-G5: what survives crashes and power loss, and what damage is reported.

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { CorruptLogError, inspectLog, ManualClock, openQueue } from '../src/index.mjs';
import { crashAt, runChild } from './helpers/crash.mjs';
import { tempDir } from './helpers/tmp.mjs';

const clock = () => new ManualClock(1_000);

function seed(t, count = 3) {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: clock() });
  for (let i = 0; i < count; i += 1) queue.enqueue('x', { i });
  queue.close();
  return { dir, log: path.join(dir, 'wal.log') };
}

const payloads = (dir) => openQueue(dir, { clock: clock() }).listJobs().map((j) => j.payload.i);

test('a write after a cut-off tail is not lost behind it (G3)', (t) => {
  const { dir, log } = seed(t);
  fs.truncateSync(log, fs.statSync(log).size - 7);
  const queue = openQueue(dir, { clock: clock() });
  assert.equal(queue.stats().tornTailsDropped, 1);
  queue.enqueue('x', { i: 99 });
  queue.close();
  // Before the fix this reopened with CorruptLogError, or lost the new job.
  assert.deepEqual(payloads(dir), [0, 1, 99]);
});

test('a torn tail is cut off on disk, so a second reader sees a clean log', (t) => {
  const { dir, log } = seed(t);
  fs.appendFileSync(log, Buffer.from([0xad, 0xfb, 5, 0, 0]));
  openQueue(dir, { clock: clock() }).close();
  assert.equal(inspectLog(dir).tail, null);
});

test('a tail of zeros, as a power cut can leave, opens and is replaced', (t) => {
  const { dir, log } = seed(t);
  fs.appendFileSync(log, Buffer.alloc(300));
  const queue = openQueue(dir, { clock: clock() });
  queue.enqueue('x', { i: 7 });
  queue.close();
  assert.deepEqual(payloads(dir), [0, 1, 2, 7]);
});

test('a last record with a bad checksum is a torn write, even if followed by garbage', (t) => {
  const { dir, log } = seed(t);
  const bytes = fs.readFileSync(log);
  bytes[bytes.length - 3] ^= 0xff;
  fs.writeFileSync(log, Buffer.concat([bytes, Buffer.alloc(40, 0x11)]));
  const queue = openQueue(dir, { clock: clock() });
  assert.equal(queue.stats().total, 2);
  queue.close();
});

test('damage in the middle of the log is reported with its offset and nothing is changed (G4)', (t) => {
  const { dir, log } = seed(t, 4);
  const view = inspectLog(dir);
  const victim = view.frames[1];
  const bytes = fs.readFileSync(log);
  bytes[victim.offset + 14] ^= 0xff; // inside the second record's payload
  fs.writeFileSync(log, bytes);
  const before = fs.readFileSync(log);
  assert.throws(
    () => openQueue(dir, { clock: clock() }),
    (err) => err instanceof CorruptLogError && err.offset === victim.offset,
  );
  assert.throws(() => inspectLog(dir), CorruptLogError);
  assert.ok(fs.readFileSync(log).equals(before), 'the file was left as it was found');
});

test('a damaged length field is damage when records follow it, not a cut-off tail (G4)', (t) => {
  const { dir, log } = seed(t, 4);
  const victim = inspectLog(dir).frames[1];
  const bytes = fs.readFileSync(log);
  bytes.writeUInt32LE(0x03000000, victim.offset + 2); // claims a 48 MiB record
  fs.writeFileSync(log, bytes);
  assert.throws(
    () => openQueue(dir, { clock: clock() }),
    (err) => err instanceof CorruptLogError && err.offset === victim.offset,
  );
});

test('garbage in the middle that was appended after is reported, not skipped (G4)', (t) => {
  const { dir, log } = seed(t, 2);
  const frames = inspectLog(dir).frames;
  const bytes = fs.readFileSync(log);
  const gap = Buffer.alloc(25, 0x22);
  const damaged = Buffer.concat([bytes.subarray(0, frames[1].offset), gap, bytes.subarray(frames[1].offset)]);
  fs.writeFileSync(log, damaged);
  assert.throws(
    () => openQueue(dir, { clock: clock() }),
    (err) => err instanceof CorruptLogError && err.offset === frames[1].offset,
  );
});

test('a log far bigger than one read chunk opens with every job in it (G5)', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: clock(), compactAfterBytes: 0 });
  const padding = 'p'.repeat(2_000);
  const total = 1_800; // about 3.5 MiB of log
  for (let start = 0; start < total; start += 300) {
    queue.enqueueMany(Array.from({ length: 300 }, (_, i) => ({ type: 'x', payload: { n: start + i, padding } })));
  }
  const job = queue.claim('w');
  queue.complete(job.id, job.token, 'done');
  queue.close();

  assert.ok(fs.statSync(path.join(dir, 'wal.log')).size > 3 * 1024 * 1024);
  const reopened = openQueue(dir, { clock: clock(), compactAfterBytes: 0 });
  assert.equal(reopened.stats().total, total);
  assert.equal(reopened.stats().done, 1);
  // New ids carry on from the full count, and a compaction keeps every job.
  assert.equal(reopened.enqueue('x', null).id, `j${total + 1}`);
  reopened.compact();
  assert.equal(reopened.stats().total, total + 1);
});

test('a single record larger than a read chunk is read back (G5)', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: clock(), compactAfterBytes: 0 });
  const { id } = queue.enqueue('x', { blob: 'b'.repeat(3 * 1024 * 1024) });
  queue.enqueue('x', 'after');
  queue.close();
  const reopened = openQueue(dir, { clock: clock(), compactAfterBytes: 0 });
  assert.equal(reopened.getJob(id).payload.blob.length, 3 * 1024 * 1024);
  assert.equal(reopened.stats().total, 2);
  reopened.compact();
  assert.equal(reopened.getJob(id).payload.blob.length, 3 * 1024 * 1024);
});

test('a record over the format limit is refused before anything is written (G5)', (t) => {
  const { dir, log } = seed(t, 1);
  const queue = openQueue(dir, { clock: clock() });
  const before = fs.statSync(log).size;
  assert.throws(() => queue.enqueue('x', { blob: 'b'.repeat(65 * 1024 * 1024) }), /limit/);
  assert.equal(fs.statSync(log).size, before);
  assert.equal(queue.stats().total, 1);
});

test('a caller cannot change the queue by changing what it passed in', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: clock() });
  const payload = { list: [1] };
  const { id } = queue.enqueue('x', payload);
  payload.list.push(2);
  assert.deepEqual(queue.getJob(id).payload, { list: [1] });
});

test('killed at every point of an append, under power loss, the log opens and holds what was acknowledged', (t) => {
  for (const point of ['wal.before-append', 'wal.mid-append', 'wal.after-write', 'wal.after-fsync']) {
    const dir = tempDir(t);
    runChild(dir, 'enqueue', { arg: 2 });
    const { fired } = crashAt(t, dir, 'enqueue', `${point}=kill`, { arg: 1 });
    assert.ok(fired, point);
    const jobs = payloads(dir);
    // The crashed call was never acknowledged, except at after-fsync, where it is durable.
    assert.deepEqual(jobs.slice(0, 2), [0, 1], point);
    assert.equal(jobs.length, point === 'wal.after-fsync' ? 3 : 2, point);
    // And the queue carries on.
    const queue = openQueue(dir, { clock: clock() });
    queue.enqueue('x', { i: 50 });
    queue.close();
    assert.equal(payloads(dir).at(-1), 50, point);
  }
});

test('a brand new queue killed while it is being created opens afterwards (G2)', (t) => {
  for (const point of ['wal.after-create']) {
    const dir = tempDir(t);
    const { fired } = crashAt(t, dir, 'open', `${point}=kill`);
    assert.ok(fired);
    const queue = openQueue(dir, { clock: clock() });
    queue.enqueue('x', 1);
    assert.equal(queue.stats().total, 1);
  }
});

test('killed at every point of a compaction, under power loss, nothing is lost and compaction works again (G2, G12)', (t) => {
  for (const point of ['compact.after-tmp-write', 'compact.before-rename', 'compact.after-rename']) {
    const dir = tempDir(t);
    runChild(dir, 'enqueue', { arg: 5 });
    const { fired } = crashAt(t, dir, 'compact', `${point}=kill`);
    assert.ok(fired, point);
    const queue = openQueue(dir, { clock: clock() });
    assert.equal(queue.stats().total, 5, point);
    assert.deepEqual(
      queue.listJobs().map((j) => j.payload.i),
      [0, 1, 2, 3, 4],
      point,
    );
    // Whatever the dead compaction left behind must not stop the next one.
    queue.compact();
    queue.enqueue('x', { i: 5 });
    queue.close();
    assert.equal(payloads(dir).length, 6, point);
  }
});

// G6-G14: several processes on one log, leases, retries, keys and compaction.
// Two Queue instances over one directory stand in for two processes: each has its
// own state and offset, and they share only the log and the lock.

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { clearFailpoints, ManualClock, onFailpoint, openQueue, StaleLeaseError } from '../src/index.mjs';
import { tempDir } from './helpers/tmp.mjs';

const BACKOFF = { baseMs: 100, factor: 2, maxMs: 10_000 };

function pair(t, options = {}) {
  t.after(clearFailpoints);
  const clock = new ManualClock(10_000);
  const dir = tempDir(t);
  const open = () => openQueue(dir, { clock, backoff: BACKOFF, ...options });
  return { clock, dir, a: open(), b: open(), open };
}

test('two processes racing to claim one job: only one gets it (G6)', (t) => {
  const { a, b } = pair(t);
  a.enqueue('x', 1);
  let rival = null;
  // The moment between "a job is due" and "take the lock" is where another process gets in.
  onFailpoint('claim.before-lock', () => {
    clearFailpoints();
    rival = b.claim('rival');
  });
  const mine = a.claim('me');
  assert.ok(rival, 'the rival got the job');
  assert.equal(mine, null, 'the slower claimer must not take it again');
  assert.equal(a.getJob(rival.id).fence, 1);
  assert.equal(a.getJob(rival.id).attempts, 1);
});

test('a claim that lost the race takes the next job instead', (t) => {
  const { a, b } = pair(t);
  const first = a.enqueue('x', 1).id;
  const second = a.enqueue('x', 2).id;
  onFailpoint('claim.before-lock', () => {
    clearFailpoints();
    assert.equal(b.claim('rival').id, first);
  });
  assert.equal(a.claim('me').id, second);
});

test('a heartbeat is seen by the process that reaps leases (G7)', (t) => {
  const { a, b, clock } = pair(t);
  a.enqueue('x', 1);
  const job = a.claim('w', { leaseMs: 500 });
  for (let i = 0; i < 6; i += 1) {
    clock.advance(400);
    a.heartbeat(job.id, job.token, { leaseMs: 500 });
    assert.deepEqual(b.reapExpired(), [], 'a live worker keeps its job');
  }
  clock.advance(500);
  assert.equal(b.reapExpired().length, 1);
  assert.throws(() => a.heartbeat(job.id, job.token), StaleLeaseError);
});

test('a reaper working from out-of-date state does not reap a job that was committed or extended (G7)', (t) => {
  const { a, b, clock } = pair(t);
  a.enqueue('x', 1);
  a.enqueue('x', 2);
  const slow = a.claim('w', { leaseMs: 500 });
  const done = a.claim('w', { leaseMs: 500 });
  clock.advance(600);
  onFailpoint('reap.before-lock', () => {
    clearFailpoints();
    a.complete(done.id, done.token, 'ok');
    a.heartbeat(slow.id, slow.token, { leaseMs: 500 });
  });
  assert.deepEqual(b.reapExpired(), []);
  assert.equal(a.getJob(done.id).status, 'done');
  assert.equal(a.getJob(slow.id).status, 'leased');
});

test('an old token cannot touch a job that someone else holds now (G8)', (t) => {
  const { a, b, clock } = pair(t);
  const { id } = a.enqueue('x', 1);
  const old = a.claim('w1', { leaseMs: 500 });
  clock.advance(500);
  b.reapExpired();
  clock.advance(100);
  const current = b.claim('w2');
  assert.equal(current.id, id);
  assert.notEqual(current.token, old.token);
  assert.throws(() => a.heartbeat(id, old.token), StaleLeaseError);
  assert.throws(() => a.fail(id, old.token, 'late'), StaleLeaseError);
  assert.throws(() => a.complete(id, old.token, 'late'), StaleLeaseError);
  assert.equal(a.getJob(id).status, 'leased');
  assert.equal(a.getJob(id).lease.worker, 'w2');
});

test('a token is never issued twice for a job, even across requeueDead (G6)', (t) => {
  const { a, clock } = pair(t, { backoff: { baseMs: 0 } });
  const { id } = a.enqueue('x', 1, { maxAttempts: 1 });
  const seen = [];
  for (let round = 0; round < 3; round += 1) {
    const job = a.claim('w');
    seen.push(job.token);
    a.fail(job.id, job.token, 'no');
    assert.equal(a.getJob(id).status, 'dead');
    a.requeueDead(id);
    clock.advance(1);
  }
  assert.equal(new Set(seen).size, 3, `tokens ${seen}`);
});

test('a retry keeps the due time it was given when it failed, through restarts and compaction (G9)', (t) => {
  const { a, clock, open } = pair(t);
  const { id } = a.enqueue('x', 1);
  const job = a.claim('w');
  const { retryAt } = a.fail(job.id, job.token, 'boom');
  assert.equal(retryAt, 10_100);

  clock.advance(5_000);
  const other = open();
  assert.equal(other.getJob(id).availableAt, 10_100, 'a restarted process sees the same time');
  a.compact();
  assert.equal(open().getJob(id).availableAt, 10_100);
  assert.equal(other.claim('w').id, id, 'and the job is due, not pushed out to the restart');
});

test('attempts, backoff and maxAttempts survive compaction and restart (G9, G11)', (t) => {
  const { a, clock, open } = pair(t, { backoff: { baseMs: 100, factor: 2, maxMs: 100_000 } });
  const { id } = a.enqueue('x', 1, { maxAttempts: 4 });
  const delays = [];
  let queue = a;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const job = queue.claim('w');
    assert.equal(job.attempt, attempt);
    const out = queue.fail(job.id, job.token, `fail ${attempt}`);
    delays.push(out.retryAt - clock.now());
    queue.compact();
    queue = open();
    clock.advance(out.retryAt - clock.now());
  }
  assert.deepEqual(delays, [100, 200, 400]);
  const last = queue.claim('w');
  assert.equal(queue.fail(last.id, last.token, 'last').status, 'dead');
  assert.equal(queue.getJob(id).attempts, 4);
});

test('compaction changes nothing observable but retention (G11)', (t) => {
  const { a, clock } = pair(t, { backoff: { baseMs: 100 } });
  a.enqueue('hi', { n: 1 }, { priority: 5, key: 'k1', maxAttempts: 7 });
  a.enqueue('lo', { n: 2 });
  a.enqueue('later', { n: 3 }, { delayMs: 5_000 });
  const leased = a.claim('w', { leaseMs: 900 });
  const failed = a.claim('w');
  a.fail(failed.id, failed.token, 'oops');
  clock.advance(1);
  const before = a.listJobs();
  a.compact();
  assert.deepEqual(a.listJobs(), before);
  assert.equal(a.getJob(leased.id).lease.fence, leased.token);
});

test('a key is remembered after its job is pruned, across compactions and restarts (G10)', (t) => {
  const { a, clock, open } = pair(t, { retainCompletedMs: 1_000 });
  const first = a.enqueue('report', { month: 'sep' }, { key: 'report-sep' });
  const job = a.claim('w');
  a.complete(job.id, job.token, { sent: true });

  clock.advance(2_000);
  a.compact(); // the job is dropped here
  assert.equal(a.getJob(first.id), null);

  for (let round = 0; round < 3; round += 1) {
    const again = open().enqueue('report', { month: 'sep' }, { key: 'report-sep' });
    assert.equal(again.deduped, true, `round ${round}`);
    assert.equal(again.id, first.id);
    assert.equal(again.status, 'done');
    assert.deepEqual(again.result, { sent: true });
    a.compact();
    clock.advance(24 * 60 * 60 * 1000);
  }
  assert.equal(a.stats().total, 0, 'nothing was created');

  // Past its time to live (7 days from enqueue) the key is free again.
  clock.advance(8 * 24 * 60 * 60 * 1000);
  a.compact();
  assert.equal(open().enqueue('report', null, { key: 'report-sep' }).deduped, false);
});

test('two processes racing on one key create one job (G10)', (t) => {
  const { a, b } = pair(t);
  let rival;
  onFailpoint('enqueue.before-lock', () => {
    clearFailpoints();
    rival = b.enqueue('x', 'rival', { key: 'only-one' });
  });
  const mine = a.enqueue('x', 'mine', { key: 'only-one' });
  assert.equal(rival.deduped, false);
  assert.equal(mine.deduped, true);
  assert.equal(mine.id, rival.id);
  assert.equal(a.stats().total, 1);
});

test('a process follows a compaction that made the log bigger than it was (G13)', (t) => {
  const { a, b } = pair(t);
  a.enqueue('x', 1);
  b.stats(); // b has read the log as it is now
  const oldSize = fs.statSync(path.join(b.dir, 'wal.log')).size;
  // The snapshot of one small job is larger than its single record.
  a.compact();
  const newSize = fs.statSync(path.join(b.dir, 'wal.log')).size;
  assert.ok(newSize >= oldSize, `precondition: ${newSize} should not be smaller than ${oldSize}`);
  assert.equal(b.stats().total, 1);
  assert.equal(b.enqueue('x', 2).id, 'j2');
  assert.equal(a.stats().total, 2);
});

test('every process follows a compaction by another, repeatedly (G13)', (t) => {
  const { a, b } = pair(t);
  for (let round = 0; round < 5; round += 1) {
    a.enqueue('x', round);
    a.compact();
    const job = b.claim('w');
    assert.ok(job, `round ${round}`);
    b.complete(job.id, job.token, round);
    b.compact();
  }
  assert.equal(a.stats().done, 5);
  assert.equal(a.stats().total, 5);
});

test('a temp file left by a dead compaction does not block the next one (G12)', (t) => {
  const { a, dir } = pair(t);
  a.enqueue('x', 1);
  fs.writeFileSync(path.join(dir, 'wal.log.compact'), 'left over from a crash');
  a.compact();
  assert.equal(a.stats().generation, 2);
  assert.equal(fs.existsSync(path.join(dir, 'wal.log.compact')), false);
});

test('a compaction that fails leaves no temp file and the next one succeeds (G12)', (t) => {
  const { a, dir } = pair(t);
  a.enqueue('x', 1);
  onFailpoint('compact.before-rename', () => {
    throw Object.assign(new Error('operation not permitted'), { code: 'EPERM' });
  });
  assert.throws(() => a.compact(), /EPERM|not permitted/);
  clearFailpoints();
  assert.equal(fs.existsSync(path.join(dir, 'wal.log.compact')), false);
  assert.equal(a.stats().total, 1);
  a.enqueue('x', 2);
  a.compact();
  assert.equal(a.stats().total, 2);
  assert.equal(a.stats().generation, 2);
});

test('automatic compaction stays cheap when the live state is bigger than the threshold (G14)', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: new ManualClock(0), compactAfterBytes: 4_000 });
  const filler = 'f'.repeat(500);
  // Live state of about 20 KB, five times the threshold.
  queue.enqueueMany(Array.from({ length: 40 }, (_, n) => ({ type: 'x', payload: { n, filler } })));
  assert.ok(queue.stats().logBytes > 4_000);
  const start = queue.stats().generation;
  for (let i = 0; i < 100; i += 1) queue.enqueue('x', { i });
  const compactions = queue.stats().generation - start;
  assert.ok(compactions <= 3, `${compactions} compactions for 100 small writes`);
  assert.equal(queue.stats().total, 140);
});

test('a failing automatic compaction is reported and is not retried on every write', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir, { clock: new ManualClock(0), compactAfterBytes: 1_500 });
  t.after(clearFailpoints);
  let attempts = 0;
  onFailpoint('compact.before-rename', () => {
    attempts += 1;
    throw new Error('blocked');
  });
  for (let i = 0; i < 60; i += 1) queue.enqueue('x', { i, pad: 'p'.repeat(30) });
  assert.match(queue.stats().lastCompactionError, /blocked/);
  assert.ok(attempts < 20, `${attempts} attempts`);
  clearFailpoints();
  for (let i = 0; i < 60; i += 1) queue.enqueue('x', { i, pad: 'p'.repeat(30) });
  assert.equal(queue.stats().lastCompactionError, null);
  assert.equal(queue.stats().total, 120);
});

test('cancelled jobs are pruned like other finished jobs', (t) => {
  const clock = new ManualClock(0);
  const queue = openQueue(tempDir(t), { clock, retainCompletedMs: 1_000 });
  const { id } = queue.enqueue('x', 1);
  queue.cancel(id);
  clock.advance(1_000);
  queue.compact();
  assert.equal(queue.getJob(id), null);
});

// RFC 007: exactly-once completion. Receipts, results, reclaiming a dead worker's
// leases, the crash table, and the worker and pool behaviour around it.

import assert from 'node:assert/strict';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import {
  clearFailpoints,
  JobRunner,
  LockTimeoutError,
  ManualClock,
  onFailpoint,
  openQueue,
  StaleLeaseError,
  UnknownJobError,
  WorkerPool,
} from '../src/index.mjs';
import { normaliseHandlers } from '../src/worker/registry.mjs';
import { crashAt, runChild } from './helpers/crash.mjs';
import { defer, readLedger, tempDir, waitUntil } from './helpers/tmp.mjs';

const HANDLERS = fileURLToPath(new URL('./helpers/handlers.mjs', import.meta.url));

function setup(t, options = {}) {
  t.after(clearFailpoints);
  const clock = new ManualClock(50_000);
  const dir = tempDir(t);
  const open = () => openQueue(dir, { clock, backoff: { baseMs: 1_000, factor: 2, maxMs: 60_000 }, ...options });
  return { clock, dir, open, queue: open() };
}

function claimed(queue, worker = 'w', leaseMs = 10_000) {
  const { id } = queue.enqueue('x', null);
  const job = queue.claim(worker, { leaseMs });
  assert.equal(job.id, id);
  return job;
}

test('complete returns a receipt, and a repeat with the same token returns the same one', (t) => {
  const { queue, clock } = setup(t);
  const job = claimed(queue);
  const first = queue.complete(job.id, job.token, { sent: true });
  assert.deepEqual(first, {
    id: job.id,
    outcome: 'committed',
    token: job.token,
    result: { sent: true },
    completedAt: 50_000,
    completionSeq: 1,
  });

  clock.advance(5_000);
  const size = queue.stats().logBytes;
  const again = queue.complete(job.id, job.token, { different: 'result' });
  assert.deepEqual(again, { ...first, outcome: 'already-committed' });
  assert.equal(queue.stats().logBytes, size, 'nothing is written for a repeat');
});

test('a repeat is recognised after a restart and after a compaction', (t) => {
  const { queue, open } = setup(t);
  const job = claimed(queue);
  const first = queue.complete(job.id, job.token, [1, 2]);
  queue.compact();
  assert.deepEqual(open().complete(job.id, job.token, 'x'), { ...first, outcome: 'already-committed' });
  assert.deepEqual(queue.complete(job.id, job.token, 'x'), { ...first, outcome: 'already-committed' });
});

test('any other token, or a pruned job, is refused and nothing changes', (t) => {
  const { queue, clock } = setup(t, { retainCompletedMs: 1_000 });
  const job = claimed(queue);
  assert.throws(() => queue.complete(job.id, job.token + 1, 'x'), StaleLeaseError);
  queue.complete(job.id, job.token, 'real');
  assert.throws(() => queue.complete(job.id, job.token + 1, 'x'), StaleLeaseError);
  assert.throws(() => queue.complete(job.id, job.token - 1, 'x'), StaleLeaseError);
  assert.equal(queue.getJob(job.id).result, 'real');
  clock.advance(1_000);
  queue.compact();
  assert.throws(() => queue.complete(job.id, job.token, 'x'), UnknownJobError);
});

test('a lease past its deadline can still commit until someone acts on it', (t) => {
  const { queue, clock } = setup(t);
  const job = claimed(queue, 'w', 500);
  clock.advance(10_000);
  assert.equal(queue.complete(job.id, job.token, 'late but first').outcome, 'committed');

  const second = claimed(queue, 'w', 500);
  clock.advance(10_000);
  queue.reapExpired();
  assert.throws(() => queue.complete(second.id, second.token, 'too late'), StaleLeaseError);
});

test('getResult reports a finished job, any other job by status, and an unknown one as null', (t) => {
  const { queue, clock } = setup(t, { retainCompletedMs: 1_000 });
  const waiting = queue.enqueue('x', 1).id;
  const job = queue.claim('w');
  assert.deepEqual(queue.getResult(job.id), { id: job.id, status: 'leased' });
  assert.deepEqual(queue.getResult(waiting === job.id ? 'nope' : waiting), waiting === job.id ? null : { id: waiting, status: 'ready' });
  queue.complete(job.id, job.token, { v: 1 });
  assert.deepEqual(queue.getResult(job.id), {
    id: job.id,
    status: 'done',
    result: { v: 1 },
    token: job.token,
    attempts: 1,
    completedAt: 50_000,
    completionSeq: 1,
  });
  assert.equal(queue.getResult('j999'), null);
  clock.advance(1_000);
  queue.compact();
  assert.equal(queue.getResult(job.id), null);
});

test('completions lists commits in order, numbered across restarts, compaction and pruning', (t) => {
  const { queue, clock, open } = setup(t, { retainCompletedMs: 10_000 });
  const finish = (result) => {
    const job = claimed(queue);
    queue.complete(job.id, job.token, result);
    return job.id;
  };
  const a = finish('a');
  const b = finish('b');
  queue.compact();
  const c = finish('c');
  assert.deepEqual(
    queue.completions().map((e) => [e.seq, e.id, e.result]),
    [[1, a, 'a'], [2, b, 'b'], [3, c, 'c']],
  );
  assert.deepEqual(queue.completions({ after: 1, limit: 1 }).map((e) => e.seq), [2]);
  assert.deepEqual(queue.completions({ after: 3 }), []);

  clock.advance(10_001);
  queue.compact(); // a, b and c are pruned
  assert.deepEqual(queue.completions(), []);
  const reopened = open();
  const job = claimed(reopened);
  const receipt = reopened.complete(job.id, job.token, 'd');
  assert.equal(receipt.completionSeq, 4, 'numbering carries on past what was pruned');
  assert.deepEqual(open().completions({ after: 3 }).map((e) => [e.seq, e.id, e.token]), [[4, job.id, job.token]]);
});

test('reclaimWorker gives a worker\'s jobs back at once, and only that worker\'s', (t) => {
  const { queue, clock } = setup(t);
  const mine = claimed(queue, 'dead-one');
  const other = claimed(queue, 'alive');
  const committed = claimed(queue, 'dead-one');
  queue.complete(committed.id, committed.token, 'done already');
  const size = queue.stats().logBytes;

  const out = queue.reclaimWorker('dead-one', { reason: 'worker exited' });
  assert.deepEqual(out, [{ id: mine.id, status: 'ready' }]);
  assert.equal(queue.getJob(mine.id).lastError, 'worker exited');
  assert.equal(queue.getJob(mine.id).status, 'ready');
  assert.equal(queue.getJob(other.id).status, 'leased');
  assert.equal(queue.getJob(committed.id).status, 'done');
  assert.ok(queue.stats().logBytes > size);
  assert.deepEqual(queue.reclaimWorker('dead-one'), [], 'nothing left to reclaim, nothing written');

  assert.throws(() => queue.heartbeat(mine.id, mine.token), StaleLeaseError);
  assert.throws(() => queue.complete(mine.id, mine.token, 'x'), StaleLeaseError);
  const again = queue.claim('w2');
  assert.equal(again.id, mine.id, 'runnable straight away, no backoff');
  assert.equal(again.attempt, 2);
  assert.notEqual(again.token, mine.token);
  clock.advance(0);
});

test('a reclaimed job that is out of attempts goes dead', (t) => {
  const { queue } = setup(t);
  const { id } = queue.enqueue('x', null, { maxAttempts: 1 });
  queue.claim('w');
  assert.deepEqual(queue.reclaimWorker('w', { reason: 'gone' }), [{ id, status: 'dead' }]);
  assert.equal(queue.getJob(id).status, 'dead');
  assert.equal(queue.getJob(id).lastError, 'gone');
});

test('a reclaim is the same after a restart and after a compaction', (t) => {
  const { queue, open } = setup(t);
  const job = claimed(queue, 'w');
  queue.reclaimWorker('w');
  queue.compact();
  const view = open().getJob(job.id);
  assert.equal(view.status, 'ready');
  assert.equal(view.attempts, 1);
  assert.equal(view.fence, job.token);
});

// ---- the crash table, with real processes and the power-loss model ----

test('killed part way through writing complete, the job runs again', (t) => {
  for (const point of ['wal.before-append#complete', 'wal.mid-append#complete', 'wal.after-write#complete']) {
    const { dir, open } = setup(t);
    runChild(dir, 'enqueue', { arg: 1 });
    assert.ok(crashAt(t, dir, 'run', `${point}=kill`).fired, point);
    const queue = open();
    const job = queue.listJobs()[0];
    assert.equal(job.status, 'leased', point);
    queue.reclaimWorker('doomed');
    const again = queue.claim('w2');
    assert.equal(again.id, job.id, point);
    assert.equal(queue.complete(again.id, again.token, 'second time').outcome, 'committed', point);
  }
});

test('killed after complete is durable, the job does not run again', (t) => {
  for (const point of ['wal.after-fsync#complete']) {
    const { dir, open } = setup(t);
    runChild(dir, 'enqueue', { arg: 1 });
    assert.ok(crashAt(t, dir, 'run', `${point}=kill`).fired, point);
    const queue = open();
    const job = queue.listJobs()[0];
    assert.equal(job.status, 'done', point);
    assert.deepEqual(queue.reclaimWorker('doomed'), [], point);
    assert.equal(queue.claim('w2'), null, point);
    queue.compact();
    assert.equal(open().claim('w2'), null);
    assert.equal(queue.complete(job.id, job.fence, 'x').outcome, 'already-committed');
  }
});

test('killed while a compaction runs after the commit, the commit still holds', (t) => {
  for (const point of ['compact.after-tmp-write', 'compact.before-rename', 'compact.after-rename']) {
    const { dir, open } = setup(t);
    runChild(dir, 'enqueue', { arg: 2 });
    runChild(dir, 'run');
    assert.ok(crashAt(t, dir, 'compact', `${point}=kill`).fired, point);
    const queue = open();
    assert.equal(queue.stats().done, 1, point);
    assert.equal(queue.claim('w2').payload.i, 1, 'only the other job is left to run');
    assert.equal(queue.claim('w2'), null);
  }
});

test('a completion is durable when complete returns: power loss right after loses nothing (G1)', (t) => {
  const { dir, open } = setup(t);
  runChild(dir, 'enqueue', { arg: 1 });
  // job.after-complete is the worker's point just after complete() returned.
  runChild(dir, 'run');
  assert.equal(open().stats().done, 1);
});

// ---- the worker ----

function fakeQueue(overrides) {
  const calls = [];
  const queue = {
    config: { leaseMs: 1_000 },
    calls,
    heartbeats: 0,
    jobs: [{ id: 'j1', type: 'quick', payload: null, attempt: 1, token: 1 }, { id: 'j2', type: 'quick', payload: null, attempt: 1, token: 1 }],
    claim() {
      calls.push('claim');
      return this.jobs.shift() ?? null;
    },
    heartbeat() {
      this.heartbeats += 1;
    },
    complete(id) {
      calls.push(`complete ${id}`);
      return { id, outcome: 'committed' };
    },
    fail(id) {
      calls.push(`fail ${id}`);
      return { id, status: 'ready' };
    },
    ...overrides,
  };
  return queue;
}

function runnerFor(queue, handlers, events) {
  const runner = new JobRunner({
    queue,
    workerId: 'w',
    handlers: normaliseHandlers(handlers),
    leaseMs: 1_000,
    heartbeatMs: 15,
    pollMs: 5,
    emit: (event) => {
      events.push(event);
      if (events.filter((e) => e.kind === 'job-completed' || e.kind === 'job-fenced').length >= 2) runner.stop();
    },
  });
  return runner;
}

test('a worker keeps trying to record a finished job, heartbeating, and takes no other job meanwhile', async () => {
  let failures = 0;
  const queue = fakeQueue({
    complete(id) {
      this.calls.push(`complete ${id}`);
      if (id === 'j1' && (failures += 1) <= 4) throw new LockTimeoutError('queue.lock', 10);
      return { id, outcome: 'committed' };
    },
  });
  const events = [];
  await runnerFor(queue, { quick: async () => 'r' }, events).run();
  assert.deepEqual(queue.calls.filter((c) => c !== 'claim'), ['complete j1', 'complete j1', 'complete j1', 'complete j1', 'complete j1', 'complete j2']);
  // j2 was claimed only after j1 was recorded.
  assert.deepEqual(queue.calls.slice(0, 7), ['claim', ...Array(5).fill('complete j1'), 'claim']);
  assert.ok(queue.heartbeats >= 1, 'the lease was kept alive while it retried');
  assert.equal(events.filter((e) => e.kind === 'job-completed').length, 2);
});

test('a worker that learns it was fenced reports job-fenced and stops trying', async () => {
  const queue = fakeQueue({
    complete(id) {
      this.calls.push(`complete ${id}`);
      if (id === 'j1') throw new StaleLeaseError(id, 1, 2);
      return { id, outcome: 'committed' };
    },
  });
  const events = [];
  await runnerFor(queue, { quick: async () => 'r' }, events).run();
  assert.equal(queue.calls.filter((c) => c === 'complete j1').length, 1);
  assert.deepEqual(events.filter((e) => e.kind === 'job-fenced').map((e) => e.id), ['j1']);
});

test('disk trouble while recording is waited out, as a transient error', async () => {
  let failures = 0;
  const queue = fakeQueue({
    complete(id) {
      this.calls.push(`complete ${id}`);
      if (id === 'j1' && (failures += 1) <= 2) throw Object.assign(new Error('busy'), { code: 'EBUSY' });
      return { id, outcome: 'committed' };
    },
  });
  const events = [];
  await runnerFor(queue, { quick: async () => 'r' }, events).run();
  assert.equal(queue.calls.filter((c) => c === 'complete j1').length, 3);
});

test('a result that cannot be stored fails the attempt instead of retrying forever', async (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir);
  const { id } = queue.enqueue('x', null, { maxAttempts: 1 });
  const events = [];
  const runner = new JobRunner({
    queue,
    workerId: 'w',
    handlers: normaliseHandlers({ x: async () => ({ big: 10n }) }),
    leaseMs: 5_000,
    pollMs: 5,
    emit: (e) => {
      events.push(e);
      if (e.kind === 'job-failed') runner.stop();
    },
  });
  await runner.run();
  assert.equal(queue.getJob(id).status, 'dead');
  assert.match(queue.getJob(id).lastError, /BigInt/);
});

// ---- the pool, with real worker processes ----

function pool(t, dir, ledger, extra = {}) {
  const p = new WorkerPool({
    dir,
    handlers: HANDLERS,
    pollMs: 5,
    reapMs: 10_000, // far longer than the tests, so only reclaiming can return a job early
    ...extra,
    env: { WALQ_TEST_LEDGER: ledger, ...(extra.env ?? {}) },
  });
  defer(t, () => p.stop());
  return p;
}

const starts = (ledger, id) => readLedger(ledger).filter((e) => e.event === 'start' && e.id === id).length;

for (const point of ['job.before-handler', 'job.after-handler']) {
  test(`a worker killed at ${point} has its job run again without waiting for the lease`, { timeout: 30_000 }, async (t) => {
    const dir = tempDir(t);
    const markers = tempDir(t);
    const ledger = path.join(dir, 'runs.jsonl');
    const queue = openQueue(dir);
    const { id } = queue.enqueue('quick', { n: 1 });
    const p = pool(t, dir, ledger, {
      size: 1,
      leaseMs: 120_000,
      env: { WALQ_FAILPOINTS: `${point}=kill`, WALQ_FAILPOINT_DIR: markers },
    });
    const started = performance.now();
    p.start();
    await waitUntil(() => queue.getJob(id).status === 'done', { timeoutMs: 20_000 });
    assert.ok(performance.now() - started < 15_000, 'did not wait for a 120 s lease');
    assert.equal(queue.getJob(id).attempts, 2);
    assert.equal(starts(ledger, id), point === 'job.before-handler' ? 1 : 2);
  });
}

for (const point of ['wal.after-fsync#complete', 'job.after-complete']) {
  test(`a worker killed at ${point} does not run the job again`, { timeout: 30_000 }, async (t) => {
    const dir = tempDir(t);
    const markers = tempDir(t);
    const ledger = path.join(dir, 'runs.jsonl');
    const queue = openQueue(dir);
    const { id } = queue.enqueue('quick', { n: 1 });
    const p = pool(t, dir, ledger, {
      size: 1,
      leaseMs: 120_000,
      env: { WALQ_FAILPOINTS: `${point}=kill`, WALQ_FAILPOINT_DIR: markers },
    });
    const exited = new Promise((resolve) => p.once('exit', resolve));
    p.start();
    await exited;
    await waitUntil(() => queue.getJob(id).status === 'done');
    // Give a respawned worker the chance to (wrongly) run it again.
    await new Promise((resolve) => setTimeout(resolve, 600));
    assert.equal(queue.getJob(id).attempts, 1);
    assert.equal(starts(ledger, id), 1);
    assert.equal(queue.getResult(id).completionSeq, 1);
  });
}

test('one pool reclaiming its dead worker does not touch another pool\'s workers', { timeout: 30_000 }, async (t) => {
  const dir = tempDir(t);
  const markers = tempDir(t);
  const ledger = path.join(dir, 'runs.jsonl');
  const queue = openQueue(dir);
  const slow = queue.enqueue('slow', { ms: 2_000 }).id;
  const quick = queue.enqueue('quick', { n: 1 }).id;
  const b = pool(t, dir, ledger, { size: 1, leaseMs: 120_000, types: ['slow'] });
  const a = pool(t, dir, ledger, {
    size: 1,
    leaseMs: 120_000,
    types: ['quick'],
    env: { WALQ_FAILPOINTS: 'job.before-handler=kill', WALQ_FAILPOINT_DIR: markers },
  });
  b.start();
  await waitUntil(() => queue.getJob(slow).status === 'leased');
  a.start();
  await waitUntil(() => queue.getJob(quick).status === 'done', { timeoutMs: 20_000 });
  await waitUntil(() => queue.getJob(slow).status === 'done', { timeoutMs: 20_000 });
  assert.equal(queue.getJob(quick).attempts, 2);
  assert.equal(queue.getJob(slow).attempts, 1, 'the other pool\'s job was left alone');
  assert.equal(starts(ledger, slow), 1);
});

test('a pool reclaims after a worker dies, even if the queue was busy at that moment', { timeout: 30_000 }, async (t) => {
  const dir = tempDir(t);
  const markers = tempDir(t);
  const ledger = path.join(dir, 'runs.jsonl');
  const queue = openQueue(dir);
  const { id } = queue.enqueue('quick', { n: 1 });
  const p = pool(t, dir, ledger, {
    size: 1,
    leaseMs: 120_000,
    reapMs: 100,
    env: { WALQ_FAILPOINTS: 'job.before-handler=kill', WALQ_FAILPOINT_DIR: markers },
  });
  let failed = 0;
  const realReclaim = p.queue?.reclaimWorker;
  p.start();
  const original = p.queue.reclaimWorker.bind(p.queue);
  p.queue.reclaimWorker = (...args) => {
    failed += 1;
    if (failed === 1) throw new LockTimeoutError('queue.lock', 1);
    return original(...args);
  };
  p.on('error-event', () => {});
  await waitUntil(() => queue.getJob(id).status === 'done', { timeoutMs: 20_000 });
  assert.ok(failed >= 2, 'the failed reclaim was retried');
  assert.equal(realReclaim, undefined);
  void onFailpoint;
});

