import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { openQueue } from '../src/index.mjs';

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'walq-eperm-'));
const queue = openQueue(dir);
for (let i = 0; i < 5; i += 1) queue.enqueue('x', { i });
const log = path.join(dir, 'wal.log');

// 1. A backup-like reader: FileShare.Read only, so the file cannot be deleted or replaced.
const holder = spawn('powershell', [
  '-NoProfile', '-Command',
  `$f=[IO.File]::Open('${log}','Open','Read','Read'); Write-Host held; Start-Sleep 6; $f.Close()`,
], { stdio: ['ignore', 'pipe', 'inherit'] });
await new Promise((resolve) => holder.stdout.once('data', resolve));
try {
  queue.compact();
  console.log('compaction succeeded while held (unexpected)');
} catch (err) {
  console.log('compaction while held failed with', err.code, '|', err.message.slice(0, 80));
}
console.log('temp file left behind:', fs.existsSync(`${log}.compact`));
queue.enqueue('x', { i: 5 });
console.log('queue still works, total', queue.stats().total);
await new Promise((resolve) => holder.on('exit', resolve));
console.log('after release:', JSON.stringify(queue.compact()));

// 2. walq tail running while compactions happen.
const tail = spawn(process.execPath, ['src/cli.mjs', 'tail', dir], { stdio: ['ignore', 'pipe', 'inherit'] });
let out = '';
tail.stdout.on('data', (d) => (out += d));
await new Promise((r) => setTimeout(r, 500));
for (let i = 0; i < 3; i += 1) {
  queue.enqueue('x', { late: i });
  queue.compact();
  await new Promise((r) => setTimeout(r, 450));
}
tail.kill();
console.log('compactions with tail running ok; generation', queue.stats().generation, 'lastError', queue.stats().lastCompactionError);
console.log(out.split('\n').filter(Boolean).slice(-6).join('\n'));
fs.rmSync(dir, { recursive: true, force: true });
process.exit(0);

