const fs = require('fs');
function edit(file, pairs) {
  let s = fs.readFileSync(file, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) throw new Error(`${file}: missing ${a.slice(0, 60)}`);
    s = s.replace(a, b);
  }
  fs.writeFileSync(file, s);
}

edit('docs/api.md', [
  [
    '**`heartbeat(id, token, { leaseMs })`** returns `{ leaseUntil }`. Throws `StaleLeaseError` if the lease is no longer yours.',
    '**`heartbeat(id, token, { leaseMs })`** returns `{ leaseUntil }`. Throws `StaleLeaseError` if the lease is no longer yours. The extension is written to the log, so every process sees it, including whichever one runs the reaper.',
  ],
  [
    '**`complete(id, token, result)`** records the result. Throws `StaleLeaseError` if the lease is no longer yours. RFC 007 changes what this returns.',
    "**`complete(id, token, result)`** commits the result and returns a receipt `{ id, outcome, token, result, completedAt, completionSeq }`. The commit is the moment the record is durable, and that happens before the call returns. `outcome` is `'committed'` the first time. A repeat with the token that committed, even after a restart or a compaction, returns `outcome: 'already-committed'` with the stored `result`, `completedAt` and `completionSeq`, ignores the result passed in, and writes nothing. Any other token throws `StaleLeaseError` and changes nothing. A job that has been pruned throws `UnknownJobError`. A lease past its deadline can still commit, as long as no reaper, reclaim or cancel has acted on it. See [rfc-007](rfc-007-exactly-once-completion.md).\n\n" +
      "**`getResult(id)`** returns `{ id, status: 'done', result, token, attempts, completedAt, completionSeq }` for a finished job, `{ id, status }` for any other job, and `null` for a job that never existed or has been pruned. Results are kept for `retainCompletedMs`.\n\n" +
      "**`completions({ after = 0, limit })`** returns the retained commits in commit order, `[{ seq, id, token, result, completedAt }]`, with `seq > after`. Numbers start at 1 and go up by one per commit, across restarts and compactions, including after older entries were pruned. Readers keep their own position. Jobs that finished before this existed have no number and are not listed.\n\n" +
      "**`reclaimWorker(workerId, { reason })`** gives up every lease held by a worker known to be dead, at once, and returns `[{ id, status }]`. Each job is `ready` and runnable straight away (no backoff), with `reason` as its `lastError`, or `dead` if it is out of attempts. The attempt counts. Jobs the worker already committed are not touched. The old token is stale from then on. Only call this for a worker that cannot still be running. `WorkerPool` makes its worker ids unique (`w<n>.<pool id>`), so one pool never reclaims another's.",
  ],
  [
    '`exit` fires when a worker exits,',
